-- =====================================================================
-- Katalog e-bike'ów (wygenerowane przez catalog/build.py – nie edytuj ręcznie)
-- =====================================================================

on conflict (id) do update
    set brand = excluded.brand,
        model = excluded.model,
        category = excluded.category,
        price = excluded.price,
        color = excluded.color,
        featured = excluded.featured,
        sort = excluded.sort,
        image_url = excluded.image_url,
        image_credit = excluded.image_credit,
        image_source = excluded.image_source,
        popularity = excluded.popularity,
        active = true;

-- modele spoza pliku (np. usunięte marki) ukrywamy – cele użytkowników zostają
update public.bike_catalog set active = false
 where id not in ('eride-mini', 'eride-pro-s', 'eride-ss2', 'eride-se', 'eride-ss25', 'eride-pro-ss3', 'eride-ss4', 'eride-pro-sr', 'surron-hyperbee', 'surron-lbx', 'surron-l1e', 'surron-lb2', 'surron-lb2-l3e', 'surron-ultrabee', 'surron-ultrabee-t', 'surron-stormbee', 'talaria-x3', 'talaria-x3-l1e', 'talaria-xxx', 'talaria-xxx-l1e', 'talaria-sting-mx3', 'talaria-sting-mx4', 'talaria-sting-sx4', 'talaria-mx5', 'talaria-mx5-pro', 'talaria-dragon', 'talaria-komodo', 'stark-varg-mx', 'stark-varg-mx-alpha', 'stark-varg-ex', 'stark-varg-ex-alpha', 'stark-varg-sm', 'stark-varg-sm-alpha', 'stark-varg-mx-fe', 'stark-varg-ex-fe', 'ktm-sx-e2', 'ktm-sx-e3', 'ktm-sx-e5', 'ktm-freeride-e', 'segway-xafari', 'segway-xyber', 'segway-x160', 'segway-x260', '79bike-falcon-m', '79bike-falcon-pro', '79bike-falcon-pro-ltd', '79bike-falcon-m-gt', 'super73-mzft', 'super73-zmiami', 'super73-zx', 'super73-m1d', 'super73-b1g', 'super73-s2', 'super73-rx', 'super73-r-adventure');
